export function detectLang(){
  const q=new URLSearchParams(location.search).get('lang');
  if(q==='en'||q==='ja'||q==='ar') return q;
  try{const s=localStorage.getItem('tft_lang');if(s==='en'||s==='ja'||s==='ar') return s;}catch(e){}
  const p=location.pathname;const m=p.match(/(?:^|\/)(en|ja)(?:\/|$)/);
  return m?m[1]:'ar';
}
export let lang=detectLang();
export let patchVersion='';
export function setPatchVersion(v){patchVersion=v;applyLanguage()}
export const t=k=>((copy[lang]&&copy[lang][k])||copy.en[k]||k).replace('{v}',patchVersion);
export function localize(value){return value?.[lang]??value?.en??value?.ar??''}
export const LANGS=['ar','en','ja'];
export const LANG_LABEL={ar:'عربي',en:'EN',ja:'日本語'};
export function nextLang(){return LANGS[(LANGS.indexOf(lang)+1)%LANGS.length]}
export function localePath(page='',target=lang){
  const clean=String(page||'').replace(/^\/+|\/+$/g,'');
  let path=!clean||clean==='index.html'?'index.html':clean;
  if(target&&target!=='ar') path+=(path.includes('?')?'&':'?')+'lang='+target;
  return path;
}
export function currentLocaleUrl(target=lang){
  const u=new URL(location.href);
  const filtered=u.pathname.split('/').filter(Boolean).filter(x=>x!=='en'&&x!=='ja');
  u.pathname='/'+(filtered.join('/')||'');
  if(target==='ar') u.searchParams.delete('lang');
  else u.searchParams.set('lang',target);
  return u.pathname+u.search+u.hash;
}
export function applyLanguage(){
  document.documentElement.lang=lang;
  document.documentElement.dir=lang==='ar'?'rtl':'ltr';
  document.querySelectorAll('[data-i18n]').forEach(el=>el.innerHTML=t(el.dataset.i18n));
  document.querySelectorAll('[data-i18n-placeholder]').forEach(el=>el.placeholder=t(el.dataset.i18nPlaceholder));
  document.querySelectorAll('.lang-toggle').forEach(b=>b.textContent=LANG_LABEL[nextLang()]);
}
function setupMobileNav(){
  const header=document.querySelector('.site-header');
  const nav=header&&header.querySelector('nav');
  if(!header||!nav||header.querySelector('.nav-toggle')) return;
  const btn=document.createElement('button');
  btn.className='nav-toggle';
  btn.type='button';
  btn.setAttribute('aria-label','Menu');
  btn.setAttribute('aria-expanded','false');
  btn.innerHTML='<span></span><span></span><span></span>';
  btn.addEventListener('click',()=>{
    const open=header.classList.toggle('nav-open');
    btn.setAttribute('aria-expanded',open?'true':'false');
  });
  const langBtn=header.querySelector('.lang-toggle');
  let actions=header.querySelector('.header-actions');
  if(!actions){
    actions=document.createElement('div');
    actions.className='header-actions';
    if(langBtn) actions.appendChild(langBtn);
    actions.appendChild(btn);
    header.appendChild(actions);
  } else if(!actions.contains(btn)){
    actions.appendChild(btn);
  }
  nav.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{
    header.classList.remove('nav-open');
    btn.setAttribute('aria-expanded','false');
  }));
}
function setupMobileTabbar(){
  if(document.querySelector('.mobile-tabbar')) return;
  const page=(location.pathname.split('/').pop()||'index.html').split('?')[0];
  const tabs=[
    {href:'index.html',key:'navHome',ico:'🏠'},
    {href:'comps.html',key:'navComps',ico:'🧩'},
    {href:'items.html',key:'navItems',ico:'⚒️'},
    {href:'champions.html',key:'navChampions',ico:'👤'},
    {href:'augments.html',key:'navAugments',ico:'✨'}
  ];
  const bar=document.createElement('nav');
  bar.className='mobile-tabbar';
  bar.setAttribute('aria-label','Mobile');
  bar.innerHTML=tabs.map(tab=>{
    const isComp=page==='comp.html'&&tab.href==='comps.html';
    const active=page===tab.href || (page===''&&tab.href==='index.html') || isComp ? 'active' : '';
    return `<a class="${active}" href="${localePath(tab.href)}"><span class="tab-ico">${tab.ico}</span><span>${t(tab.key)}</span></a>`;
  }).join('');
  document.body.appendChild(bar);
}
export function setupLanguage(onChange){
  applyLanguage();
  setupMobileNav();
  setupMobileTabbar();
  document.querySelectorAll('.lang-toggle').forEach(b=>b.addEventListener('click',()=>{
    const next=nextLang();
    try{localStorage.setItem('tft_lang',next);}catch(e){}
    location.assign(currentLocaleUrl(next));
  }));
  onChange?.();
}
